refentry.refsect1:
  &reftitle.examples;

   Пример использования функции pcntl_waitpid


<?php

function checkChild(int $pid, bool $wait): void
{
    $flags = ($wait ? 0 : WNOHANG);
    $deadPid = pcntl_waitpid($pid, $status, $flags, $rusage);
    if ($deadPid === -1) {
        $errNo = pcntl_get_last_error();
        $errMsg = pcntl_strerror($errNo);
        print "РОДИТЕЛЬ: не удалось выполнить pcntl_waitpid ({$errNo}): {$errMsg}\n";
    } elseif ($deadPid === 0) {
        print "РОДИТЕЛЬ pcntl_waitpid: завершённых дочерних процессов нет.\n";
    } elseif (pcntl_wifexited($status)) {
        print "РОДИТЕЛЬ pcntl_waitpid: дочерний процесс {$deadPid} завершился со статусом: "
            . pcntl_wexitstatus($status) . "\n";
        var_dump($rusage);
    } else {
        print "РОДИТЕЛЬ pcntl_waitpid: дочерний процесс {$deadPid} был завершён сигналом: "
            . pcntl_wtermsig($status) . "\n";
    }
}

$parentPid = getmypid();
$forkedPid = pcntl_fork();
if ($forkedPid == -1) {
    die('Не удалось выполнить fork');
} else if ($forkedPid) {
    // Родительский процесс
    print "РОДИТЕЛЬ {$parentPid} создал дочерний процесс {$forkedPid}\n";

    print "РОДИТЕЛЬ проверяет завершённые дочерние процессы\n";
    checkChild($forkedPid, false);

    // Не позволяет дочернему процессу остаться «зомби»
    print "РОДИТЕЛЬ ожидает завершения дочернего процесса\n";
    checkChild($forkedPid, true);

    print "РОДИТЕЛЬ проверяет завершённые дочерние процессы\n";
    checkChild($forkedPid, false);

    print "РОДИТЕЛЬ завершает работу\n";
} else {
    // Дочерний процесс
    $pid = getmypid();
    print "ДОЧЕРНИЙ {$pid} спит\n";
    sleep(10);
    print "ДОЧЕРНИЙ завершает работу\n";
    exit(7);
}
